def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def countPerfectSubtrees(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    h = [1] * n
    perfect = [False] * n
    count = 0
    for k in range(n - 1, -1, -1):
        a, b = left[k], right[k]
        if a == -1 and b == -1:
            perfect[k] = True
        else:
            if a != -1 and b != -1:
                perfect[k] = perfect[a] and perfect[b] and h[a] == h[b]
            h[k] = 1 + max(h[a] if a != -1 else 0, h[b] if b != -1 else 0)
        count += perfect[k]
    return count
